<?php
namespace App\Http\Controllers; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller {public function create(){return view('auth.login');}public function store(Request $request){$c=$request->validate(['email'=>['required','email'],'password'=>['required']]);if(!Auth::attempt($c,$request->boolean('remember')))return back()->withErrors(['email'=>'بيانات الدخول غير صحيحة.'])->onlyInput('email');$request->session()->regenerate();return redirect()->intended(route('sales.index'));}public function createFirstUser(){abort_if(User::query()->exists(),404);return view('auth.register');}public function storeFirstUser(Request $request){abort_if(User::query()->exists(),404);$data=$request->validate(['name'=>['required','string','max:255'],'email'=>['required','email','max:255','unique:users'],'password'=>['required','confirmed','min:8']]);$user=User::create(['name'=>$data['name'],'email'=>$data['email'],'password'=>Hash::make($data['password'])]);Auth::login($user);$request->session()->regenerate();return redirect()->route('sales.index');}public function destroy(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login');}}
